-- Theory questions for STA 112. Safe to run twice.
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Basic probability$q$, $q$Define a sample space and an event. State the three axioms of probability.$q$, 5, $q$A sample space S is the set of all possible outcomes of an experiment. An event is any subset of the sample space. The axioms of probability are: (1) For any event A, P(A) is greater than or equal to 0. (2) P(S) = 1. (3) If A and B are mutually exclusive events then P(A or B) = P(A) + P(B), and this extends to any countable collection of mutually exclusive events.$q$, $q$[{"t":"Sample space defined as the set of all possible outcomes","m":1},{"t":"Event defined as a subset of the sample space","m":1},{"t":"Axiom 1: P(A) is not negative","m":1},{"t":"Axiom 2: P(S) = 1","m":1},{"t":"Axiom 3: additivity for mutually exclusive events","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define a sample space and an event. State the three axioms of probability.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Basic probability$q$, $q$State the addition rule for two events. If P(A) = 0.4, P(B) = 0.5 and P(A and B) = 0.2, find P(A or B).$q$, 5, $q$The addition rule is P(A or B) = P(A) + P(B) - P(A and B). The overlap is subtracted because it is counted twice. Here P(A or B) = 0.4 + 0.5 - 0.2 = 0.7. For mutually exclusive events P(A and B) = 0 and the rule reduces to P(A or B) = P(A) + P(B).$q$, $q$[{"t":"General formula P(A or B) = P(A) + P(B) - P(A and B)","m":2},{"t":"Explains why the overlap is subtracted","m":1},{"t":"Substitutes correctly","m":1},{"t":"Answer 0.7","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the addition rule for two events. If P(A) = 0.4, P(B) = 0.5 and P(A and B) = 0.2, find P(A or B).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Conditional probability$q$, $q$Define conditional probability and independence of two events. A bag has 3 red and 2 blue balls. Two balls are drawn one after the other without replacement. Find the probability that both are red.$q$, 5, $q$The conditional probability of A given B is P(A|B) = P(A and B)/P(B) for P(B) greater than 0. Events A and B are independent if P(A and B) = P(A) P(B), which means P(A|B) = P(A). For the draws, P(first red) = 3/5. Given the first is red, 2 red remain among 4 balls, so P(second red | first red) = 2/4. The probability both are red is 3/5 x 2/4 = 6/20 = 3/10 = 0.3.$q$, $q$[{"t":"Conditional probability formula P(A|B) = P(A and B)/P(B)","m":1},{"t":"Independence: P(A and B) = P(A) P(B)","m":1},{"t":"P(first red) = 3/5","m":1},{"t":"P(second red given first red) = 2/4","m":1},{"t":"Answer 3/10","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define conditional probability and independence of two events. A bag has 3 red and 2 blue balls. Two balls are drawn one after the other without replacement. Find the probability that both are red.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Bayes theorem$q$, $q$State Bayes' theorem. Machine A makes 60 percent of the items in a factory and machine B makes 40 percent. 2 percent of A's items are defective and 5 percent of B's items are defective. An item is picked at random and found to be defective. What is the probability that it came from machine B?$q$, 10, $q$Bayes' theorem: P(B_i|D) = P(D|B_i) P(B_i) divided by the sum over j of P(D|B_j) P(B_j). Here P(A) = 0.6, P(B) = 0.4, P(D|A) = 0.02 and P(D|B) = 0.05. By total probability P(D) = 0.6 x 0.02 + 0.4 x 0.05 = 0.012 + 0.020 = 0.032. Then P(B|D) = (0.4 x 0.05)/0.032 = 0.020/0.032 = 0.625. So there is a 62.5 percent chance the defective item came from machine B.$q$, $q$[{"t":"Correct statement of Bayes' theorem","m":2},{"t":"Identifies the priors and the defect rates","m":2},{"t":"Total probability P(D) = 0.032","m":3},{"t":"Applies Bayes to get 0.020/0.032","m":2},{"t":"Answer 0.625","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State Bayes' theorem. Machine A makes 60 percent of the items in a factory and machine B makes 40 percent. 2 percent of A's items are defective and 5 percent of B's items are defective. An item is picked at random and found to be defective. What is the probability that it came from machine B?$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Random variables$q$, $q$Define a random variable. Distinguish between a discrete and a continuous random variable, giving one example of each.$q$, 5, $q$A random variable is a function that assigns a real number to each outcome in a sample space. A discrete random variable takes a finite or countable set of values, usually from counting. Example: the number of heads in three tosses of a coin. A continuous random variable can take any value in an interval, usually from measuring. Example: the height of a student or the time taken to finish an exam. Probabilities of discrete variables come from a probability mass function and those of continuous variables from areas under a density curve.$q$, $q$[{"t":"Definition: a rule giving a number to each outcome","m":1},{"t":"Discrete: countable values","m":1},{"t":"Correct discrete example","m":1},{"t":"Continuous: any value in an interval","m":1},{"t":"Correct continuous example","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define a random variable. Distinguish between a discrete and a continuous random variable, giving one example of each.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Binomial distribution$q$, $q$State the conditions for a binomial distribution and give its probability mass function, mean and variance. A fair coin is tossed 5 times. Find the probability of exactly 2 heads.$q$, 10, $q$Conditions: a fixed number n of trials, each trial has two outcomes (success or failure), the probability of success p is the same in each trial, and the trials are independent. The probability mass function is P(X = x) = C(n, x) p^x q^(n - x) for x = 0, 1, ..., n, where q = 1 - p. The mean is np and the variance is npq. For the coin, n = 5, p = 1/2 and x = 2. P(X = 2) = C(5, 2) (1/2)^2 (1/2)^3 = 10 x 1/32 = 10/32 = 5/16 = 0.3125.$q$, $q$[{"t":"Conditions: fixed n, two outcomes, constant p, independent trials","m":2},{"t":"Formula P(X = x) = C(n, x) p^x q^(n - x)","m":2},{"t":"Mean np and variance npq","m":2},{"t":"Substitutes n = 5, p = 1/2, x = 2 and C(5, 2) = 10","m":2},{"t":"Answer 5/16 or 0.3125","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the conditions for a binomial distribution and give its probability mass function, mean and variance. A fair coin is tossed 5 times. Find the probability of exactly 2 heads.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Expectation and variance$q$, $q$Define the expectation and variance of a discrete random variable. X takes the values 1, 2 and 3 with probabilities 0.2, 0.5 and 0.3. Find E(X) and Var(X).$q$, 10, $q$The expectation of a discrete random variable is E(X) = sum of x P(X = x). The variance is Var(X) = E[(X - mu)^2] = E(X^2) - [E(X)]^2. Here E(X) = 1(0.2) + 2(0.5) + 3(0.3) = 0.2 + 1.0 + 0.9 = 2.1. E(X^2) = 1(0.2) + 4(0.5) + 9(0.3) = 0.2 + 2.0 + 2.7 = 4.9. Var(X) = 4.9 - (2.1)^2 = 4.9 - 4.41 = 0.49.$q$, $q$[{"t":"E(X) = sum of x P(X = x)","m":1},{"t":"Var(X) = E(X^2) - [E(X)]^2","m":2},{"t":"E(X) = 2.1","m":2},{"t":"E(X^2) = 4.9","m":3},{"t":"Var(X) = 0.49","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define the expectation and variance of a discrete random variable. X takes the values 1, 2 and 3 with probabilities 0.2, 0.5 and 0.3. Find E(X) and Var(X).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Normal distribution$q$, $q$State four properties of the normal distribution. If X is normally distributed with mean 50 and variance 16, find the probability that X is greater than 58. (Use P(Z less than 2) = 0.9772.)$q$, 5, $q$Properties: the curve is bell shaped and symmetric about the mean. Mean, median and mode are equal. The total area under the curve is 1. The curve approaches the horizontal axis but never touches it, and about 68 percent of values lie within one standard deviation of the mean, 95 percent within two. Standardise: the standard deviation is the square root of 16 = 4, so Z = (58 - 50)/4 = 2. P(X greater than 58) = P(Z greater than 2) = 1 - 0.9772 = 0.0228.$q$, $q$[{"t":"Any two correct properties (bell shaped and symmetric, mean = median = mode)","m":1},{"t":"Any two further correct properties (total area 1, empirical 68-95 rule)","m":1},{"t":"Standard deviation 4 found from variance 16","m":1},{"t":"Z = (58 - 50)/4 = 2","m":1},{"t":"Answer 0.0228","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State four properties of the normal distribution. If X is normally distributed with mean 50 and variance 16, find the probability that X is greater than 58. (Use P(Z less than 2) = 0.9772.)$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Counting techniques$q$, $q$Distinguish between a permutation and a combination. In how many ways can 5 different books be arranged on a shelf, and in how many ways can a committee of 3 be chosen from 7 people?$q$, 5, $q$A permutation is an arrangement in which order matters. A combination is a selection in which order does not matter. The number of arrangements of 5 different books is 5! = 120. The number of ways to choose 3 people from 7 is C(7, 3) = 7!/(3! 4!) = (7 x 6 x 5)/(3 x 2 x 1) = 35.$q$, $q$[{"t":"Permutation: order matters","m":1},{"t":"Combination: order does not matter","m":1},{"t":"5! = 120","m":1},{"t":"C(7, 3) = 35","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Distinguish between a permutation and a combination. In how many ways can 5 different books be arranged on a shelf, and in how many ways can a committee of 3 be chosen from 7 people?$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Counting techniques$q$, $q$Find the number of different arrangements of the letters of the word STATISTICS.$q$, 5, $q$STATISTICS has 10 letters. S appears 3 times, T appears 3 times, I appears 2 times, A once and C once. When letters repeat, divide by the factorial of each repeat. The number of arrangements is 10!/(3! x 3! x 2!) = 3,628,800/(6 x 6 x 2) = 3,628,800/72 = 50,400.$q$, $q$[{"t":"Counts 10 letters and the repeats (3, 3, 2)","m":2},{"t":"Formula 10!/(3! 3! 2!)","m":2},{"t":"Answer 50,400","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Find the number of different arrangements of the letters of the word STATISTICS.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Basic probability$q$, $q$Explain the difference between mutually exclusive events and independent events. If A and B are independent with P(A) = 0.3 and P(B) = 0.4, find P(A and B) and P(A or B).$q$, 5, $q$Mutually exclusive events cannot happen together, so P(A and B) = 0. Independent events do not affect each other, so P(A and B) = P(A) P(B). Two events with non-zero probabilities cannot be both mutually exclusive and independent. For the independent events, P(A and B) = 0.3 x 0.4 = 0.12. Then P(A or B) = 0.3 + 0.4 - 0.12 = 0.58.$q$, $q$[{"t":"Mutually exclusive: P(A and B) = 0","m":1},{"t":"Independent: P(A and B) = P(A)P(B)","m":1},{"t":"P(A and B) = 0.12","m":1},{"t":"P(A or B) = 0.58","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Explain the difference between mutually exclusive events and independent events. If A and B are independent with P(A) = 0.3 and P(B) = 0.4, find P(A and B) and P(A or B).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Total probability$q$, $q$Box 1 contains 3 red and 2 black balls. Box 2 contains 2 red and 4 black balls. A box is chosen at random and a ball is drawn from it. Find the probability that the ball is red.$q$, 5, $q$Each box is chosen with probability 1/2. P(red | box 1) = 3/5 and P(red | box 2) = 2/6 = 1/3. By the law of total probability P(red) = (1/2)(3/5) + (1/2)(1/3) = 3/10 + 1/6 = 9/30 + 5/30 = 14/30 = 7/15, which is about 0.467.$q$, $q$[{"t":"P(each box) = 1/2","m":1},{"t":"Conditional probabilities 3/5 and 1/3","m":1},{"t":"Uses total probability formula","m":1},{"t":"Answer 7/15","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Box 1 contains 3 red and 2 black balls. Box 2 contains 2 red and 4 black balls. A box is chosen at random and a ball is drawn from it. Find the probability that the ball is red.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Random variables$q$, $q$A discrete random variable X has probability function p(x) = kx for x = 1, 2, 3, 4. Find k, P(X is at least 3) and E(X).$q$, 5, $q$The probabilities must add up to 1. So k(1 + 2 + 3 + 4) = 10k = 1, which gives k = 0.1. The probabilities are 0.1, 0.2, 0.3 and 0.4. P(X is at least 3) = 0.3 + 0.4 = 0.7. E(X) = 1(0.1) + 2(0.2) + 3(0.3) + 4(0.4) = 0.1 + 0.4 + 0.9 + 1.6 = 3.$q$, $q$[{"t":"States that the probabilities sum to 1","m":1},{"t":"k = 0.1","m":1},{"t":"P(X at least 3) = 0.7","m":1},{"t":"E(X) formula","m":1},{"t":"E(X) = 3","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$A discrete random variable X has probability function p(x) = kx for x = 1, 2, 3, 4. Find k, P(X is at least 3) and E(X).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Random variables$q$, $q$Define the cumulative distribution function (CDF) of a random variable and state its properties. For the variable in which p(x) = 0.1x for x = 1, 2, 3, 4, find F(2).$q$, 5, $q$The CDF is F(x) = P(X is less than or equal to x). Properties: F is non-decreasing, F(x) approaches 0 as x goes to minus infinity, and approaches 1 as x goes to plus infinity, and 0 is less than or equal to F(x) is less than or equal to 1. For the given variable F(2) = p(1) + p(2) = 0.1 + 0.2 = 0.3.$q$, $q$[{"t":"Definition F(x) = P(X less than or equal to x)","m":1},{"t":"Non-decreasing","m":1},{"t":"Limits 0 and 1","m":1},{"t":"F(2) = 0.3","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define the cumulative distribution function (CDF) of a random variable and state its properties. For the variable in which p(x) = 0.1x for x = 1, 2, 3, 4, find F(2).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Continuous distributions$q$, $q$A continuous random variable has probability density function f(x) = kx^2 for 0 less than or equal to x less than or equal to 3 and 0 elsewhere. Find k, P(X less than 1) and E(X).$q$, 6, $q$A density function must integrate to 1. The integral from 0 to 3 of kx^2 dx = k(27/3) = 9k, so 9k = 1 and k = 1/9. P(X less than 1) is the integral from 0 to 1 of x^2/9 dx = (1/9)(1/3) = 1/27. E(X) is the integral from 0 to 3 of x(x^2/9) dx = (1/9)(3^4/4) = (1/9)(81/4) = 9/4 = 2.25.$q$, $q$[{"t":"Total integral equals 1","m":1},{"t":"k = 1/9","m":1},{"t":"P(X less than 1) = 1/27","m":2},{"t":"E(X) = integral of x f(x)","m":1},{"t":"E(X) = 2.25","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$A continuous random variable has probability density function f(x) = kx^2 for 0 less than or equal to x less than or equal to 3 and 0 elsewhere. Find k, P(X less than 1) and E(X).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Poisson distribution$q$, $q$State the conditions for a Poisson distribution and give its mean and variance. If X has a Poisson distribution with mean 2, find P(X = 0) and P(X less than or equal to 1). (Use e^-2 = 0.1353.)$q$, 6, $q$The Poisson distribution models the number of events in a fixed interval when events occur independently, at a constant average rate, and one at a time. P(X = x) = e^-lambda lambda^x/x! The mean and the variance are both equal to lambda. With lambda = 2: P(X = 0) = e^-2 = 0.1353. P(X = 1) = 2e^-2 = 0.2706. So P(X less than or equal to 1) = 0.1353 + 0.2706 = 0.4059.$q$, $q$[{"t":"Conditions: independent events, constant rate, fixed interval","m":1},{"t":"Formula and mean = variance = lambda","m":2},{"t":"P(X = 0) = 0.1353","m":1},{"t":"P(X = 1) = 0.2706","m":1},{"t":"P(X at most 1) = 0.406","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the conditions for a Poisson distribution and give its mean and variance. If X has a Poisson distribution with mean 2, find P(X = 0) and P(X less than or equal to 1). (Use e^-2 = 0.1353.)$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Uniform and exponential distributions$q$, $q$State the mean and variance of a uniform distribution on the interval (a, b). If X is uniform on (2, 8), find its mean, variance and P(X greater than 6).$q$, 5, $q$For a uniform distribution on (a, b) the density is 1/(b - a). The mean is (a + b)/2 and the variance is (b - a)^2/12. For (2, 8) the mean is 10/2 = 5 and the variance is 36/12 = 3. P(X greater than 6) = (8 - 6)/(8 - 2) = 2/6 = 1/3.$q$, $q$[{"t":"Density 1/(b - a)","m":1},{"t":"Mean formula and value 5","m":1},{"t":"Variance formula and value 3","m":2},{"t":"P(X greater than 6) = 1/3","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the mean and variance of a uniform distribution on the interval (a, b). If X is uniform on (2, 8), find its mean, variance and P(X greater than 6).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Uniform and exponential distributions$q$, $q$State the probability density function and the mean of an exponential distribution with parameter lambda. If lambda = 0.5, find P(X greater than 2). (Use e^-1 = 0.3679.)$q$, 5, $q$The exponential density is f(x) = lambda e^(-lambda x) for x at least 0. The mean is 1/lambda and the variance is 1/lambda^2. The survival probability is P(X greater than x) = e^(-lambda x). With lambda = 0.5 and x = 2, P(X greater than 2) = e^(-1) = 0.3679.$q$, $q$[{"t":"Density f(x) = lambda e^(-lambda x)","m":1},{"t":"Mean 1/lambda","m":1},{"t":"Survival formula e^(-lambda x)","m":1},{"t":"Answer 0.3679","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the probability density function and the mean of an exponential distribution with parameter lambda. If lambda = 0.5, find P(X greater than 2). (Use e^-1 = 0.3679.)$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Normal distribution$q$, $q$X is normally distributed with mean 100 and variance 25. Find P(95 less than X less than 110). (Use P(Z less than 2) = 0.9772 and P(Z less than 1) = 0.8413.)$q$, 5, $q$The standard deviation is the square root of 25 = 5. Standardise: z1 = (95 - 100)/5 = -1 and z2 = (110 - 100)/5 = 2. P(-1 less than Z less than 2) = P(Z less than 2) - P(Z less than -1). By symmetry P(Z less than -1) = 1 - 0.8413 = 0.1587. So the probability is 0.9772 - 0.1587 = 0.8185.$q$, $q$[{"t":"Standard deviation 5","m":1},{"t":"z-values -1 and 2","m":1},{"t":"Uses symmetry for P(Z less than -1) = 0.1587","m":1},{"t":"Answer 0.8185","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$X is normally distributed with mean 100 and variance 25. Find P(95 less than X less than 110). (Use P(Z less than 2) = 0.9772 and P(Z less than 1) = 0.8413.)$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Moment generating functions$q$, $q$Define the moment generating function (m.g.f.) of a random variable. Find the m.g.f. of a Bernoulli variable with success probability p and use it to find the mean.$q$, 5, $q$The m.g.f. of X is M(t) = E(e^(tX)). The nth moment is found from the nth derivative at t = 0. A Bernoulli variable takes value 1 with probability p and 0 with probability q = 1 - p. So M(t) = e^0 q + e^t p = q + p e^t. The first derivative is M'(t) = p e^t. At t = 0, M'(0) = p, so the mean is E(X) = p.$q$, $q$[{"t":"Definition M(t) = E(e^(tX))","m":1},{"t":"Moments from derivatives at t = 0","m":1},{"t":"M(t) = q + p e^t","m":2},{"t":"Mean = M'(0) = p","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define the moment generating function (m.g.f.) of a random variable. Find the m.g.f. of a Bernoulli variable with success probability p and use it to find the mean.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Joint distributions$q$, $q$Define the covariance of two random variables and state what it says about independence. If E(X) = 2, E(Y) = 3 and E(XY) = 7, find Cov(X, Y).$q$, 5, $q$The covariance is Cov(X, Y) = E(XY) - E(X)E(Y). It measures how two variables vary together. If X and Y are independent then E(XY) = E(X)E(Y), so the covariance is 0. However, a zero covariance does not by itself prove independence. Here Cov(X, Y) = 7 - (2)(3) = 7 - 6 = 1, a positive covariance, so the variables tend to increase together and are not independent.$q$, $q$[{"t":"Formula Cov = E(XY) - E(X)E(Y)","m":1},{"t":"Independent variables have zero covariance","m":1},{"t":"Zero covariance does not prove independence","m":1},{"t":"Cov = 1","m":1},{"t":"Interprets the sign","m":1}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$Define the covariance of two random variables and state what it says about independence. If E(X) = 2, E(Y) = 3 and E(XY) = 7, find Cov(X, Y).$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Inequalities$q$, $q$State Chebyshev's inequality. A variable has mean 50 and standard deviation 5. Find a lower bound for the probability that it lies between 40 and 60.$q$, 5, $q$Chebyshev's inequality says that for any random variable with mean mu and standard deviation sigma, P(|X - mu| less than k sigma) is at least 1 - 1/k^2 for k greater than 1. Here 40 and 60 are 10 units from the mean, which is k = 10/5 = 2 standard deviations. So the probability is at least 1 - 1/4 = 0.75.$q$, $q$[{"t":"Statement with k standard deviations","m":2},{"t":"Identifies k = 2","m":1},{"t":"Bound 1 - 1/k^2 = 0.75","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State Chebyshev's inequality. A variable has mean 50 and standard deviation 5. Find a lower bound for the probability that it lies between 40 and 60.$q$);
insert into public.theory_questions (course_code, course_title, topic, question, marks, model_answer, key_points)
select $q$STA 112$q$, $q$Probability and Distribution Theory$q$, $q$Expectation and variance$q$, $q$State the effect on the mean and variance of changing X to aX + b. If E(X) = 4 and Var(X) = 9, find E(Y) and Var(Y) for Y = 3X - 2.$q$, 5, $q$E(aX + b) = aE(X) + b and Var(aX + b) = a^2 Var(X). Adding a constant b shifts the mean but does not change the spread. For Y = 3X - 2: E(Y) = 3(4) - 2 = 10 and Var(Y) = 3^2 x 9 = 81.$q$, $q$[{"t":"E(aX + b) = aE(X) + b","m":1},{"t":"Var(aX + b) = a^2 Var(X)","m":1},{"t":"E(Y) = 10","m":1},{"t":"Var(Y) = 81","m":2}]$q$::jsonb
where not exists (select 1 from public.theory_questions t where t.question = $q$State the effect on the mean and variance of changing X to aX + b. If E(X) = 4 and Var(X) = 9, find E(Y) and Var(Y) for Y = 3X - 2.$q$);
select course_code, count(*) as questions from public.theory_questions group by course_code order by course_code;
